/*
 * A400131  Positive integers k that are not narcissistic (Armstrong) numbers
 *          in any base b with 2 <= b <= k-2.
 * https://oeis.org/A400131
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) is the n‑th positive integer that is NOT narcissistic in
 *            any base 2 ≤ b ≤ k−2. The sequence is generated by a brute‑force
 *            scan of the integers, keeping a list of the accepted values. The
 *            implementation memoizes the results so that calls can be made in
 *            any order
 * Range:     u8 n <= 69, u16 n <= 69, u32 n <= 69, u64 n <= 69, u128 n <= 69,
 *            big any n
 * Validated: partial, pass, 69 terms through n = 69 (2026-11-03)
 * Helpers:   mem
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include "../utils/mem.h"

/* largest b such that b^exp <= limit */
static uint64_t floor_pow_limit(uint64_t limit, uint64_t exp)
{
    if (exp == 0) return limit;
    uint64_t lo = 1, hi = limit;
    while (lo < hi) {
        uint64_t mid = (lo + hi + 1) >> 1;
        __int128 p = 1;
        for (uint64_t i = 0; i < exp; ++i) {
            p *= mid;
            if (p > limit) break;
        }
        if (p <= limit)
            lo = mid;
        else
            hi = mid - 1;
    }
    return lo;
}

/* test whether k is narcissistic in base b with length l */
static bool narc_in_base(uint64_t k, uint64_t b, uint64_t l)
{
    uint64_t temp = k;
    uint64_t sum = 0;
    uint64_t len = 0;
    while (temp > 0) {
        uint64_t digit = temp % b;
        uint64_t pow = 1;
        if (digit != 0) {
            for (uint64_t j = 0; j < l; ++j) {
                if (pow > k / digit) { pow = k + 1; break; }
                pow *= digit;
            }
        } else {
            pow = 0;
        }
        if (pow > k) { sum = k + 1; break; }
        sum += pow;
        if (sum > k) break;
        temp /= b;
        ++len;
    }
    if (len != l) return false;
    return sum == k;
}

/* integer square root, floor */
static uint64_t isqrt_uint64(uint64_t x)
{
    uint64_t lo = 0, hi = (x >> 1) + 1;
    while (lo < hi) {
        uint64_t mid = (lo + hi + 1) >> 1;
        if (mid * mid <= x)
            lo = mid;
        else
            hi = mid - 1;
    }
    return lo;
}

/* test whether k is narcissistic in any base 2 <= b <= k-2 */
static bool is_narcissistic(uint64_t k)
{
    if (k <= 2) return false;   /* base range empty */

    /* case l = 2 -- efficiently checked via digit equations */
    uint64_t sqrtk = isqrt_uint64(k);
    for (uint64_t d1 = 1; d1 <= sqrtk; ++d1) {
        uint64_t d1sq = d1 * d1;          /* d1^2 <= k */
        uint64_t d0sq = k - d1sq;
        uint64_t d0 = isqrt_uint64(d0sq);
        if (d0 * d0 != d0sq) continue;
        if ((k - d0) % d1 != 0) continue;
        uint64_t b = (k - d0) / d1;
        if (b < 2 || b > k - 2) continue;
        if (d1 >= b || d0 >= b) continue;
        return true;
    }

    /* cases l >= 3 */
    uint64_t tmp = k;
    uint64_t max_len = 1;
    while (tmp > 1) {
        tmp >>= 1;
        ++max_len;
    }

    for (uint64_t l = 3; l <= max_len; ++l) {
        uint64_t lower = floor_pow_limit(k, l) + 1;
        uint64_t upper = floor_pow_limit(k, l - 1);
        if (lower < 2) lower = 2;
        if (upper > k - 2) upper = k - 2;
        if (lower > upper) continue;
        for (uint64_t b = lower; b <= upper; ++b) {
            if (narc_in_base(k, b, l)) return true;
        }
    }
    return false;
}

/* sequence generator with memoisation */
seq_t a(idx_t n)
{
    static seq_t *terms = NULL;
    static size_t terms_len = 0;  /* number of stored terms */
    static size_t terms_cap = 0;  /* allocated capacity */
    static uint64_t checked_up_to = 0;  /* last integer checked */

    /* Return immediately if the term we need is already stored */
    if (terms_len >= n)
        return terms[n - 1];

    /* Ensure the array has enough capacity for the new terms */
    if (terms_cap < terms_len + n) {
        size_t new_cap = terms_cap ? terms_cap * 2 : 16;
        while (new_cap < terms_len + n) new_cap *= 2;
        seq_t *new_terms = mem_resize(seq_t, terms, new_cap);
        if (!new_terms) abort();
        terms = new_terms;
        terms_cap = new_cap;
    }

    /* Scan integers until we have at least n terms */
    while (terms_len < n) {
        ++checked_up_to;
        if (!is_narcissistic(checked_up_to)) {
            terms[terms_len++] = (seq_t)checked_up_to;
        }
    }

    return terms[n - 1];
}
